<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {useStudio,id} from './studioContext'
import {clone} from './editRuntime'
import {locateQuotation} from './historyRuntime'
const s=useStudio(),data=ref<any>(null),tables=ref<Record<string,any[]>>({}),tab=ref('works'),selected=ref(0),busy=ref(false),error=ref(''),notice=ref(''),plan=ref<any>(null),reviewed=ref(false)
const baseline=ref(''),dirty=computed(()=>JSON.stringify(tables.value)!==baseline.value)
const row=computed(()=>tables.value[tab.value]?.[selected.value])
const fields=computed(()=>Object.entries(data.value?.definitions[tab.value]?.fields||{}))
const locked=computed(()=>busy.value||s.rootLocked('/workspace/historyLibrary',true))
const path=()=>`/projects/${s.p.value.id}/history`
function accept(value:any){data.value=value;tables.value=clone(value.draft||value.tables);baseline.value=JSON.stringify(tables.value);selected.value=0;reviewed.value=false;plan.value=null}
async function load(){const pid=s.p.value.id;const value=await s.api(path());if(s.p.value.id===pid)accept(value)}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await fn()}catch(e:any){error.value=e.message||String(e)}finally{busy.value=false}}
async function flush(){if(!data.value||!dirty.value)return;const value=await s.api(path()+'/draft','PUT',{version:s.p.value.version,baseRevision:data.value.revision,baseDraftHash:data.value.draftHash,tables:tables.value});accept(value);await s.refresh()}
async function save(){await s.saveAll()}
const unregister=s.registerDraftSaver('history',flush,()=>!!data.value&&dirty.value)
onBeforeUnmount(unregister)
async function legacy(){await run(async()=>{await s.saveAll();accept(await s.api(path()+'/legacy-candidates','POST',{version:s.p.value.version}));await s.refresh();notice.value='已建立候选，尚未确认；未调用模型'})}
async function generate(){await run(async()=>{if(dirty.value)await save();await s.generate('history');notice.value='历史候选任务已提交，仅生成草稿'})}
async function preview(){await run(async()=>{if(dirty.value)await save();await s.saveAll();plan.value=await s.api(path()+'/preview','POST',{version:s.p.value.version});reviewed.value=false})}
async function confirm(){await run(async()=>{if(!reviewed.value)return;accept(await s.api(path()+'/confirm','POST',{version:s.p.value.version,acceptRisk:!!plan.value?.requiresRisk}));await s.refresh();notice.value='历史资料已确认；点击采用才会更新制作草稿'})}
async function discard(){await run(async()=>{await s.saveAll();accept(await s.api(path()+'/discard','POST',{version:s.p.value.version}));await s.refresh()})}
async function adopt(){await run(async()=>{await s.saveAll();await s.legacy(await s.api(path()+'/adopt','POST',{version:s.p.value.version}));notice.value='已采用到制作草稿，请回到资料和人物档案核对确认；未启动模型'})}
function add(){const r:any={};for(const k of Object.keys(data.value.definitions[tab.value].fields)){r[k]=['sort_order','source_start','source_end'].includes(k)?0:k==='work_id'?s.p.value.id:k==='id'?(tab.value==='works'?s.p.value.id:id()):['episode_id','quotation_id','inference_id'].includes(k)?null:''}r.project_id=s.p.value.id;r.revision=0;tables.value[tab.value].push(r);selected.value=tables.value[tab.value].length-1}
function options(key:string){if(data.value?.enums[key])return data.value.enums[key].map((v:string)=>({id:v,name:v}));const t:any={work_id:'works',person_id:'persons',source_id:'hist_sources',quotation_id:'quotations',inference_id:'inferences',episode_id:'background_episodes'};if(key==='character_id')return s.entries('character').map((r:any)=>({id:r.id,name:r.draft.name}));if(!t[key])return null;return tables.value[t[key]].map((r:any)=>({id:r.id,name:r.canonical_name||r.title||r.summary||r.original_text||r.claim||r.id}))}
function label(r:any){return (r.canonical_name||r.title||r.line_text||r.original_text||r.claim||r.summary||r.presence||r.id||'新记录').slice(0,50)}
function locate(){const source=tables.value.hist_sources.find((r:any)=>r.id===row.value.source_id);if(!source)return;const location=locateQuotation(source.snapshot_text,row.value.original_text);if(!location){error.value='未在该版本核对文本中找到逐字原文';return}Object.assign(row.value,location);notice.value='已逐字定位；请继续核对版本、卷页和句子完整性'}
watch(tables,()=>{reviewed.value=false;plan.value=null},{deep:true})
watch(()=>s.p.value?.version,()=>{if(!busy.value&&!dirty.value&&!s.rootLocked('/workspace/historyLibrary',true))load().catch((e:any)=>error.value=e.message)})
watch(()=>s.p.value?.id,()=>run(load))
onMounted(()=>run(load))
</script>
<template><section class="extension-panel history-panel"><h3>历史资料库 · 八表</h3><p class="muted">项目独立保存。史书原话、研究推断与人物画像分开；论文及馆方资料保留在研究资料层。</p><p v-if="error" class="extension-error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><template v-if="data"><p>确认版本 r{{data.revision}} · {{data.draft?'有待确认草稿':'查看已确认资料'}}{{dirty?' · 有未保存编辑':''}}</p><div class="actions"><button :disabled="locked||data.draft||dirty" @click="legacy">从现有资料建立候选（不调用模型）</button><button :disabled="locked||s.generating.value" @click="generate">整理历史八表候选（调用 LLM）</button><button :disabled="locked||!dirty" @click="run(save)">保存历史草稿</button><button :disabled="locked||(!data.draft&&!dirty)" @click="preview">预览并核对历史资料</button><button :disabled="locked||!data.draft" @click="discard">撤回历史草稿</button></div>
<nav class="extension-tabs" aria-label="历史数据表"><button v-for="(definition,key) in data.definitions" :key="key" :class="{selected:tab===key}" @click="tab=String(key);selected=0">{{definition.label}} <small>{{tables[String(key)]?.length||0}}</small></button></nav>
<p><code>{{tab}}</code> · {{data.definitions[tab].label}}</p><fieldset :disabled="locked"><div class="actions"><select v-model.number="selected" aria-label="当前历史记录"><option v-for="(r,i) in tables[tab]" :value="i">{{label(r)}}</option></select><button @click="add" :disabled="tab==='works'&&tables.works.length>0">新增记录</button><button v-if="row" @click="tables[tab].splice(selected,1);selected=0">从草稿移除</button></div><p v-if="!row" class="muted">本表暂无记录。新增和编辑均先保存为草稿。</p><div v-else class="history-fields"><label v-for="([key,name]) in fields" :key="String(key)">{{name}}<small>{{key}}</small><input v-if="key==='id'||key==='content_hash'" :value="row[String(key)]" readonly><select v-else-if="options(String(key))" v-model="row[String(key)]"><option :value="null">选择／留空</option><option v-for="option in options(String(key))" :value="option.id">{{option.name}}</option></select><input v-else-if="['sort_order','source_start','source_end'].includes(String(key))" type="number" min="0" v-model.number="row[String(key)]"><textarea v-else v-model="row[String(key)]" :rows="key==='snapshot_text'?10:3"/></label></div><button v-if="row&&tab==='quotations'" @click="locate">在指定版本文本中逐字定位</button></fieldset>
<div v-if="plan" class="history-review"><h4>确认前核对</h4><p v-for="issue in plan.issues" class="extension-error">{{issue.table}}／{{issue.id}}：{{issue.message}}</p><p v-if="plan.requiresRisk">已有制作稿使用旧历史版本。确认新版本后仍需明确采用，不会自动覆盖制作内容。</p><details v-for="change in plan.changes"><summary>{{change.table}} · {{change.id}}</summary><div class="columns"><pre>{{JSON.stringify(change.before,null,2)}}</pre><pre>{{JSON.stringify(change.after,null,2)}}</pre></div></details><label class="extension-check"><input type="checkbox" v-model="reviewed" :disabled="plan.issues.length>0">我已核对版本、逐字原文、人物范围及研究判断归属</label><button class="primary" :disabled="locked||!reviewed||plan.issues.length>0" @click="confirm">确认历史资料{{plan.requiresRisk?'及采用风险':''}}</button></div>
<details v-if="data.researchNotes?.length"><summary>仅保留在研究层的判断</summary><p v-for="note in data.researchNotes">{{note}}</p></details><button :disabled="locked||!data.revision" @click="adopt">采用已确认历史资料到制作草稿（不调用模型）</button><p class="muted">采用后仍需按原规则确认资料与人物。未知画中范围、群体角色与未具名实例不会强行改成具名历史人物。</p>
</template></section></template>
<style scoped>.history-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:14px;margin-top:18px}.history-fields label{display:flex;flex-direction:column;gap:5px}.history-fields small{font-size:11px;color:#777}.history-review{margin:20px 0;padding:16px;background:#f8f5ec;border-radius:10px}.history-review pre{max-height:300px;overflow:auto;font-size:12px;white-space:pre-wrap}.history-panel fieldset{min-width:0}</style>
